namespace Cmdr.Core.Output;

/// <summary>Where an output line came from.</summary>
public enum OutputSource
{
    /// <summary>The child process's standard output.</summary>
    StdOut,

    /// <summary>The child process's standard error.</summary>
    StdErr,

    /// <summary>Lines generated by cmdr itself (run markers, log notices).</summary>
    System,
}
